// Tags: column hiding by header name Aspose.Cells | enable formula display in Excel via Aspose.Cells view settings | export workbook after column manipulation Aspose.Cells .NET | scan first row headers to hide columns Aspose.Cells | handle missing input file when loading workbook Aspose.Cells

using Aspose.Cells;
using System;
using System.IO;

// The example loads an existing XLSX file, scans the first row for headers named "Secret" or "Internal", hides those columns, notes that formula display must be configured through Excel view options, and saves the modified workbook to a new file while handling missing input files and runtime errors.
class Program
{
    static void Main()
    {
        const string inputPath = "input.xlsx";
        const string outputPath = "output.xlsx";

        // Verify that the input file exists to avoid FileNotFoundException
        if (!File.Exists(inputPath))
        {
            Console.WriteLine($"Error: Input file \"{inputPath}\" not found.");
            return;
        }

        try
        {
            // Load the workbook from the existing file
            Workbook workbook = new Workbook(inputPath);

            // Access the first worksheet (adjust index if needed)
            Worksheet sheet = workbook.Worksheets[0];

            // Header names whose columns should be hidden
            string[] headersToHide = { "Secret", "Internal" };

            // Assume headers are in the first row (zero‑based index)
            int headerRow = 0;

            // Determine the last used column in the header row
            int lastColumn = sheet.Cells.MaxColumn;

            // Scan each column in the header row
            for (int col = 0; col <= lastColumn; col++)
            {
                Cell cell = sheet.Cells[headerRow, col];
                if (cell != null && cell.Type == CellValueType.IsString)
                {
                    string header = cell.StringValue;
                    // Hide the column if the header matches one of the specified names
                    if (Array.IndexOf(headersToHide, header) >= 0)
                    {
                        sheet.Cells.HideColumn(col);
                    }
                }
            }

            // Note: Aspose.Cells does not expose a direct ShowFormula setting in recent versions.
            // If needed, you can set the workbook to display formulas via the view options when opening in Excel.

            // Save the modified workbook to a new file
            workbook.Save(outputPath);
            Console.WriteLine($"Workbook saved successfully to \"{outputPath}\".");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
